(()=>{let busy=false;
const activeFrame=s=>s?.versions?.find(v=>v.id===s.activeId)||s?.versions?.at(-1);
const canReplace=s=>!s?.activeId&&!s?.versions?.length&&s?.sourceChoice!=='own'||s?.autoFromPrevious===true;
async function sync(){if(busy||!data.project_id||typeof ShotMethods==='undefined')return;busy=true;try{const projectId=data.project_id;for(let i=1;i<(data.shots||[]).length;i++){const t=data.shots[i],prev=data.shots[i-1],state=t.frameImages?.first;if(!['first_frame','first_last_frames'].includes(ShotMethods.method(t))||!canReplace(state)||shotFrameBusy(state?.job)||typeof videoBusy==='function'&&videoBusy(t.videoJob))continue;const source=selectedShotVideo(prev);if(source?.status!=='completed'||!source.video_url||activeFrame(state)?.source_id===source.id)continue;if(typeof flushDisk==='function')await flushDisk();if(typeof diskConflict!=='undefined'&&(diskConflict||diskBusy))continue;const image=await frontFetch('/api/shot-frame/adopt-previous',{project_id:projectId,target_id:t.shot_id||t.id,source_kind:'previous_video',source_id:source.id});const current=t.frameImages?.first;if(data.project_id!==projectId||!canReplace(current)||selectedShotVideo(prev)?.id!==source.id||typeof videoBusy==='function'&&videoBusy(t.videoJob))continue;t.frameImages??={};const versions=[...(current?.versions||[])];if(!versions.some(v=>v.id===image.id))versions.push(image);t.frameImages.first={...current,versions,activeId:image.id,sourceChoice:'previous',needsReview:false,autoFromPrevious:true};save();if(tab===2&&shotVideoTarget()===t)render()}}catch{}finally{busy=false}}
setInterval(sync,5000);sync();})();